from __future__ import annotations
import cmath

def table(n: int) -> list[list[complex]]:
    if n <= 0: raise ValueError("n must be positive")
    return [[cmath.exp(2j * cmath.pi * k * x / n) for x in range(n)] for k in range(n)]

def orthogonality_error(t: list[list[complex]]) -> float:
    n = len(t)
    return max(abs(sum(t[k][j] * t[l][j].conjugate() for j in range(n))
                   - (n if k == l else 0)) for k in range(n) for l in range(n))

if __name__ == "__main__":
    for n in (2, 3, 4, 5):
        t = table(n)
        print(f"C_{n}: {n} characters; orthogonality error {orthogonality_error(t):.2e}")

