from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class Result:
    field: str
    class_number: int
    hilbert_degree: int
    principal: bool

def classify(field: str, class_number: int) -> Result:
    if class_number < 1: raise ValueError("class number must be positive")
    return Result(field, class_number, class_number, class_number == 1)

if __name__ == "__main__":
    for name, h in [("Q(i)", 1), ("Q(sqrt(-5))", 2), ("cyclic order-three model", 3)]:
        print(classify(name, h))

