from __future__ import annotations
import cmath

def cyclic_character_table(order: int) -> list[list[complex]]:
    if order <= 0:
        raise ValueError("order must be positive")
    return [[cmath.exp(2j * cmath.pi * k * j / order)
             for j in range(order)] for k in range(order)]

from __future__ import annotations

def transport_character(character: list[complex], artin: list[int]) -> list[complex]:
    n = len(character)
    if sorted(artin) != list(range(n)):
        raise ValueError("Artin table must be a permutation")
    return [character[artin[g]] for g in range(n)]

def inverse_transport(character: list[complex], artin: list[int]) -> list[complex]:
    inverse = [0] * len(artin)
    for g, c in enumerate(artin): inverse[c] = g
    return [character[inverse[c]] for c in range(len(artin))]

from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class HilbertClassFieldReport:
    class_number: int
    extension_degree: int
    principal_ideal_ring: bool
    character_count: int

def report(class_number: int) -> HilbertClassFieldReport:
    if class_number <= 0: raise ValueError("class number must be positive")
    return HilbertClassFieldReport(class_number, class_number,
                                   class_number == 1, class_number)

