from __future__ import annotations
import cmath

def roots_svg(n: int, path: str = "roots_of_unity.svg") -> None:
    if n < 1: raise ValueError("n must be positive")
    pts = [cmath.exp(2j*cmath.pi*k/n) for k in range(n)]
    circles = "".join(f'<circle cx="{200+140*z.real:.2f}" cy="{200-140*z.imag:.2f}" r="6" fill="#6c4cff"/>' for z in pts)
    labels = "".join(f'<text x="{200+160*z.real:.2f}" y="{205-160*z.imag:.2f}" text-anchor="middle">{k}</text>' for k,z in enumerate(pts))
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400"><rect width="100%" height="100%" fill="#faf9ff"/><circle cx="200" cy="200" r="140" fill="none" stroke="#aaa"/>{circles}{labels}</svg>'
    open(path,"w",encoding="utf-8").write(svg)
if __name__ == "__main__": roots_svg(8)

