#!/usr/bin/env python3
from __future__ import annotations
import cmath

def heat_svg(n: int = 8, path: str = "character_heatmap.svg") -> None:
    cells=[]; size=42
    for k in range(n):
        for j in range(n):
            phase=(cmath.phase(cmath.exp(2j*cmath.pi*k*j/n))+cmath.pi)/(2*cmath.pi)
            hue=round(360*phase)
            cells.append(f'<rect x="{50+j*size}" y="{30+k*size}" width="{size}" height="{size}" fill="hsl({hue},75%,55%)"/>')
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="{100+n*size}" height="{80+n*size}"><rect width="100%" height="100%" fill="white"/>'+''.join(cells)+'</svg>'
    open(path,"w",encoding="utf-8").write(svg)
if __name__ == "__main__": heat_svg()

